import numpy as np
import time
try:
    from scipy.optimize import linprog
    SCIPY_AVAILABLE = True
except Exception:
    SCIPY_AVAILABLE = False

ARTIFACT_PATH = "storage/verity/sumr32_best.npz"
SHRNK_ART = 1.0 - 1e-12
SHRNK_REF = 1.0 - 1e-10
INC_TOL = 1e-8
SLACK_THR = 1e-10

def _clip_to_box(C, margin=1e-4):
    return np.clip(C, margin, 1.0 - margin)

def _boundary_margins(C):
    x, y = C[:, 0], C[:, 1]
    return np.minimum(np.minimum(x, 1.0 - x), np.minimum(y, 1.0 - y))

def _pairwise_distances(C):
    diff = C[:, None, :] - C[None, :, :]
    d2 = np.sum(diff * diff, axis=-1)
    np.fill_diagonal(d2, 0.0)
    return np.sqrt(d2, out=np.zeros_like(d2), where=(d2 > 0))

def _solve_lp(C):
    n = C.shape[0]
    if not SCIPY_AVAILABLE:
        b = _boundary_margins(C)
        r = np.minimum(b, 0.01)
        return r, float(np.sum(r)), True
    b = _boundary_margins(C)
    D = _pairwise_distances(C)
    rows, rhs = [], []
    for i in range(n):
        for j in range(i + 1, n):
            row = np.zeros(n, dtype=float); row[i] = 1.0; row[j] = 1.0
            rows.append(row); rhs.append(D[i, j])
    A_ub = np.vstack(rows) if rows else None
    b_ub = np.array(rhs, dtype=float) if rows else None
    c = -np.ones(n, dtype=float)
    bounds = [(0.0, float(max(0.0, bi))) for bi in b]
    res = linprog(c, A_ub=A_ub, b_ub=b_ub, bounds=bounds, method="highs")
    if not res.success:
        return np.zeros(n, dtype=float), 0.0, False
    r = res.x.astype(float)
    return r, float(-res.fun), True

def _fallback_grid(n=32):
    xs = np.linspace(1.0/(8+1), 1.0-1.0/(8+1), 8)
    ys = np.linspace(1.0/(4+1), 1.0-1.0/(4+1), 4)
    return np.array([(x, y) for y in ys for x in xs], dtype=float)[:n]

def _load_artifact():
    try:
        data = np.load(ARTIFACT_PATH)
        C = np.array(data["centers"], dtype=float)
        r = np.array(data["radii"], dtype=float)
        return C, r
    except Exception:
        return None, None

def _micro_shrink(r, factor):
    return np.maximum(r * factor, 1e-12)

def _min_slacks(C, r):
    b = _boundary_margins(C)
    sb = float(np.min(b - r))
    D = _pairwise_distances(C)
    Rsum = r[:, None] + r[None, :]
    np.fill_diagonal(Rsum, 0.0)
    # consider i<j pairs; mask diagonal anyway
    sp = float(np.min(D - Rsum + np.eye(len(r))*1e9))
    return sp, sb

def _uniform_alpha_for_slack(C, r, target=SLACK_THR):
    # Find max alpha in (0,1] s.t. all slacks >= target after scaling radii by alpha.
    b = _boundary_margins(C)
    # Avoid divide by zero
    with np.errstate(divide='ignore', invalid='ignore'):
        a_bound = np.min((b - target) / np.maximum(r, 1e-16))
    D = _pairwise_distances(C)
    Rsum = r[:, None] + r[None, :]
    mask = ~np.eye(len(r), dtype=bool)
    denom = np.maximum(Rsum[mask], 1e-16)
    a_pair = np.min((D[mask] - target) / denom)
    alpha = min(1.0, float(a_bound), float(a_pair))
    # Guard against NaNs or negatives
    if not np.isfinite(alpha) or alpha <= 0.0:
        alpha = 0.5
    return max(0.0, min(1.0, alpha))

def _coordinate_descent_refine(C0, time_budget=180.0, inc_tol=INC_TOL):
    n = C0.shape[0]
    start = time.time()
    Cb = _clip_to_box(C0.copy(), margin=1e-4)
    rb, objb, ok = _solve_lp(Cb)
    if not ok:
        return C0, None, None, False
    step = 3e-3; min_step = 2e-4
    axes = np.array([[1.0, 0.0], [0.0, 1.0]], dtype=float)
    while time.time() - start < time_budget and step >= min_step:
        improved = False
        for i in range(n):
            for ax in axes:
                for sgn in (+1.0, -1.0):
                    if time.time() - start >= time_budget:
                        break
                    Ct = Cb.copy()
                    Ct[i] = Ct[i] + sgn * step * ax
                    Ct = _clip_to_box(Ct, margin=1e-4)
                    rt, objt, ok = _solve_lp(Ct)
                    if ok and objt > objb + inc_tol:
                        Cb, rb, objb = Ct, rt, objt
                        improved = True
                if time.time() - start >= time_budget:
                    break
            if time.time() - start >= time_budget:
                break
        if not improved:
            step *= 0.5
    return Cb, rb, objb, True

def construct_packing():
    np.random.seed(0)
    n = 32
    C_art, r_art = _load_artifact()
    if C_art is None or r_art is None or C_art.shape != (n,2) or r_art.shape != (n,):
        C0 = _clip_to_box(_fallback_grid(n), margin=1e-4)
        r0, obj0, ok = _solve_lp(C0)
        if not ok:
            b = _boundary_margins(C0)
            r0 = np.minimum(b, 0.01)
        base_sum = float(np.sum(_micro_shrink(r0, SHRNK_ART)))
    else:
        C0 = _clip_to_box(C_art, margin=1e-4)
        base_sum = float(np.sum(_micro_shrink(r_art, SHRNK_ART)))

    improved = False
    if SCIPY_AVAILABLE:
        Cref, rref, objref, ok = _coordinate_descent_refine(C0)
        if ok and rref is not None:
            r_ref_shrunk = _micro_shrink(rref, SHRNK_REF)
            # Enforce strict slack threshold for persistence/return safety
            sp, sb = _min_slacks(Cref, r_ref_shrunk)
            if sp < SLACK_THR or sb < SLACK_THR:
                alpha = _uniform_alpha_for_slack(Cref, r_ref_shrunk, target=SLACK_THR)
                r_ref_shrunk = _micro_shrink(r_ref_shrunk, alpha)
                sp, sb = _min_slacks(Cref, r_ref_shrunk)
            sum_ref = float(np.sum(r_ref_shrunk))
            if sum_ref > base_sum + INC_TOL and sp >= SLACK_THR and sb >= SLACK_THR:
                # Persist improved artifact
                try:
                    np.savez(ARTIFACT_PATH, centers=Cref, radii=r_ref_shrunk, obj=sum_ref)
                except Exception:
                    pass
                improved = True
                return Cref, r_ref_shrunk

    # Fallback to current artifact with standard micro-shrink
    if C_art is not None and r_art is not None:
        return _clip_to_box(C_art, margin=1e-4), _micro_shrink(r_art, SHRNK_ART)

    # Final fallback if no artifact
    r0, obj0, ok = _solve_lp(C0)
    if not ok:
        b = _boundary_margins(C0)
        r0 = np.minimum(b, 0.01)
    return C0, _micro_shrink(r0, SHRNK_ART)
